<script lang="ts">
 import {onMount} from 'svelte';import {api} from './api';import type {Row} from './types';
 let {companyID,materials,companies}:{companyID:number;materials:Row[];companies:Row[]}=$props();
 let data:Row=$state({records:[],buyers:[],types:[]}),form:Row|null=$state(null),review:Row|null=$state(null),busy=$state(false),error=$state(''),notice=$state(''),search=$state('');
 let records=$derived(data.records.filter((r:Row)=>(!companyID||r.company_id===companyID)&&(!search||(r.code+' '+r.profile.style_name+' '+r.profile.product).toLowerCase().includes(search.toLowerCase()))));
 const fields=[['style_name','Style / concept name'],['product','Product'],['season','Season'],['fit','Fit'],['features','Features'],['waist','Waist / rise'],['pattern_reference','Pattern reference'],['customer_reference','Customer style reference'],['request_email_reference','Buyer request email / approval reference'],['request_notes','Request details'],['fabric_notes','Fabric requirements'],['trim_notes','Trim requirements'],['remarks','Remarks']];
 async function load(){data=await api('/development-masters')};onMount(()=>{load().catch(e=>error=e.message)});
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await fn()}catch(e){error=(e as Error).message}finally{busy=false}}
 function edit(r?:Row){form=r?structuredClone($state.snapshot(r)):{company_id:companyID||companies[0]?.id,buyer_id:'',material_ids:[],profile:{development_type:'Self development',charge_type:'Chargeable',charge_amount:'',currency:'USD'}}}
 async function save(action:string){await run(async()=>{const result=await api('/development-masters'+(form?.id?'/'+form.id:''),{company_id:form!.company_id,buyer_id:form!.buyer_id,material_ids:form!.material_ids,profile:form!.profile,version:form!.version,action});form=null;await load();notice=result.code+(action==='submit'?' submitted for MD / Super Admin review.':' saved.')})}
 async function approve(action:string){await run(async()=>{await api('/development-masters/'+review!.id,{action,version:review!.version,note:review!.note||''});review=null;await load();notice='Review recorded.'})}
 function dialog(node:HTMLDialogElement){node.showModal();return{destroy(){node.close()}}}
</script>
<section class="panel"><div class="panel-header"><div><h3>Product-development master</h3><p>Permanent style references, linked fabric / trims, buyer requests and charge approval.</p></div>{#if data.can_edit}<button class="button primary" onclick={()=>edit()}>Add development</button>{/if}</div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="company-notice" role="status">{notice}</p>{/if}<label class="dev-search">Find a style<input bind:value={search} placeholder="Reference, style or product"/></label><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Style</th><th>Development type</th><th>Buyer / brand</th><th>Charge</th><th>Status</th><th></th></tr></thead><tbody>{#each records as r}<tr><td>{r.code}</td><td>{r.profile.style_name}<small>{r.profile.product} · {r.profile.season} · {r.profile.fit}</small></td><td>{r.profile.development_type}</td><td>{data.buyers.find((b:Row)=>b.id===r.buyer_id)?.name||'Internal self development'}</td><td>{r.profile.charge_type}</td><td>{r.status}<small>{r.review_note}</small></td><td>{#if data.can_edit&&['Draft','Changes requested'].includes(r.status)}<button class="text-button" onclick={()=>edit(r)}>Edit / submit</button>{:else}<button class="text-button" onclick={()=>review={...structuredClone($state.snapshot(r)),note:''}}>View {data.can_approve&&r.status==='Submitted'?' / review':''}</button>{/if}</td></tr>{:else}<tr><td colspan="7">No development masters in this company yet.</td></tr>{/each}</tbody></table></div></section>
{#if form}<dialog class="material-modal development-dialog" use:dialog oncancel={()=>form=null}><form onsubmit={e=>{e.preventDefault();save('save')}}><h2>{form.code||'New development master'}</h2><div class="company-form-grid"><label>Company<select bind:value={form.company_id} disabled={!!form.id} onchange={()=>{form!.buyer_id='';form!.material_ids=[]}}>{#each companies as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Buyer / brand<select bind:value={form.buyer_id}><option value="">Internal self development</option>{#each data.buyers.filter((b:Row)=>b.company_id===Number(form!.company_id)) as b}<option value={b.id}>{b.name}</option>{/each}</select></label><label>Development type<select bind:value={form.profile.development_type}>{#each data.types as t}<option>{t}</option>{/each}</select></label>{#each fields as [k,l]}<label>{l}<input bind:value={form.profile[k]} required={k==='style_name'} maxlength="2000"/></label>{/each}<label>Sample charging<select bind:value={form.profile.charge_type}><option>Chargeable</option><option>Free of charge</option></select></label><label>Charge amount<input type="number" min="0" step="any" bind:value={form.profile.charge_amount}/></label><label>Currency<select bind:value={form.profile.currency}>{#each ['USD','INR','AED','EUR','GBP','CNY'] as c}<option>{c}</option>{/each}</select></label></div><h3>Fabric & trim references</h3><p>Only active materials from this company can be selected. Blocked suppliers are excluded.</p><div class="access-checkboxes">{#each materials.filter((m:Row)=>m.company_id===Number(form!.company_id)&&m.active&&!m.supplier_blocked) as m}<label class="inline-check"><input type="checkbox" value={m.id} bind:group={form.material_ids}/>{m.code} · {m.kind}</label>{:else}<p>Ask the fabric or trims team to register a sample first.</p>{/each}</div><p class="muted">The request email reference is required for buyer samples before submission. MD / Super Admin reviews submitted requests, including free-of-charge samples.</p>{#if error}<p class="form-error">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button><button class="button secondary" disabled={busy}>Save draft</button><button type="button" class="button primary" disabled={busy} onclick={()=>save('submit')}>Submit for approval</button></footer></form></dialog>{/if}
{#if review}<dialog class="material-modal development-dialog" use:dialog oncancel={()=>review=null}><h2>{review.code} · {review.profile.style_name}</h2><div class="company-form-grid">{#each Object.entries(review.profile) as [k,v]}<div><small>{k.replaceAll('_',' ')}</small><p>{String(v)||'—'}</p></div>{/each}</div><p>Materials: {review.material_ids.map((id:number)=>materials.find((m:Row)=>m.id===id)?.code||'Restricted reference').join(', ')}</p>{#if data.can_approve&&review.status==='Submitted'}<label>Review note<textarea bind:value={review.note} maxlength="2000"></textarea></label>{/if}{#if error}<p class="form-error">{error}</p>{/if}<div class="row-actions"><button class="button secondary" onclick={()=>review=null}>Close</button>{#if data.can_approve&&review.status==='Submitted'}<button class="button secondary" disabled={busy} onclick={()=>approve('return')}>Request changes</button><button class="button primary" disabled={busy} onclick={()=>approve('approve')}>Approve</button>{/if}</div></dialog>{/if}
<style>.development-dialog{width:min(950px,94vw);max-width:950px}.dev-search{display:block;margin:0 24px 20px}small{display:block;color:var(--muted)}.access-checkboxes{max-height:250px;overflow:auto}.company-form-grid p{margin-top:3px;overflow-wrap:anywhere}</style>
